const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number.isFinite(v)?Number(v.toPrecision(6)).toString():'—';
const stops=[[68,1,84],[59,82,139],[33,145,140],[94,201,98],[253,231,37]];
export function efficiencyScale(rows){const values=rows.filter(r=>r.valid&&Number.isFinite(r.efficiency)).map(r=>r.efficiency);return values.length?{min:Math.min(...values),max:Math.max(...values)}:null;}
export function efficiencyColour(value,scale){if(!Number.isFinite(value)||!scale)return {background:'#e1e5e9',foreground:'#52616e'};const t=scale.max===scale.min ? .5 : Math.max(0,Math.min(1,(value-scale.min)/(scale.max-scale.min))),pos=t*(stops.length-1),j=Math.min(stops.length-2,Math.floor(pos)),f=pos-j,rgb=stops[j].map((v,k)=>Math.round(v+(stops[j+1][k]-v)*f));const luminance=rgb.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}).reduce((s,v,k)=>s+v*[.2126,.7152,.0722][k],0);return {background:`rgb(${rgb.join(',')})`,foreground:luminance>.179?'#000000':'#ffffff'};}
export function efficiencyHeatmap(rows,axis='vin',scale=efficiencyScale(rows),split=false){const valid=rows.filter(r=>r.valid&&[r[axis],r.outputPower,r.efficiency].every(Number.isFinite)).map(r=>({...r,[axis]:coordinateKey(r[axis]),outputPower:coordinateKey(r.outputPower)}));if(!valid.length)return '<p>No valid efficiency points.</p>';const voltages=[...new Set(valid.map(r=>r[axis]))].sort((a,b)=>a-b),powers=[...new Set(valid.map(r=>r.outputPower))].sort((a,b)=>a-b);const label=axis==='vin'?'Vin':'Vout';let html='';for(let start=0;start<powers.length;start+=split?8:powers.length){const cols=powers.slice(start,start+(split?8:powers.length));html+=`<div class="table-wrap"><table class="efficiency-heat" style="border-collapse:separate;border-spacing:3px;width:100%"><thead><tr><th>${label} [V] / Pout [W]</th>${cols.map(v=>`<th>${Number(v.toPrecision(8))}</th>`).join('')}</tr></thead><tbody>${voltages.map(v=>`<tr><th>${Number(v.toPrecision(8))}</th>${cols.map(po=>{const matches=valid.filter(r=>r[axis]===v&&r.outputPower===po),eta=matches.length?matches.reduce((s,r)=>s+r.efficiency,0)/matches.length:null,color=efficiencyColour(eta,scale);return `<td style="background:${color.background};color:${color.foreground};text-align:center;padding:12px 10px;min-width:72px;font-weight:650;border-radius:3px" title="${label}=${num(v)} V; Pout=${num(po)} W; ${eta===null?'No sampled operating point':`Efficiency=${num(eta)}%; ${matches.length} samples averaged`}">${eta===null?'—':num(eta)+'%'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
html+=`<div class="heat-legend" style="margin:14px 0 8px;font-size:12px"><strong>Efficiency [%]</strong><div style="height:13px;border-radius:3px;margin-top:6px;background:linear-gradient(to right,${stops.map(rgb=>'rgb('+rgb.join(',')+')').join(',')})"></div><div style="display:flex;justify-content:space-between;margin-top:4px"><span>${num(scale.min)}% · lower</span><span>${num(scale.max)}% · higher</span></div><p class="caption">Colours span the observed efficiency range. Grey cells are missing operating points; no values are invented.${scale.min===scale.max?' All available cells have the same efficiency.':''}</p></div>`;return html;}

// Eight significant digits merge integration round-off, not genuinely different load steps.
export const coordinateKey=v=>Number.isFinite(v)?Number(v.toPrecision(8)):v;
export function groupedHeatPoints(rows,axis='vin'){const groups=new Map();for(const r of rows){if(!r.valid||![r[axis],r.outputPower,r.efficiency].every(Number.isFinite))continue;const x=coordinateKey(r.outputPower),y=coordinateKey(r[axis]),key=x+':'+y;let g=groups.get(key);if(!g){g={x,y,efficiency:0,count:0};groups.set(key,g);}g.efficiency+=r.efficiency;g.count++;}return [...groups.values()].map(g=>({...g,efficiency:g.efficiency/g.count}));}
export function interpolateHeatPoint(points,x,y){const xs=[...new Set(points.map(p=>p.x))].sort((a,b)=>a-b),ys=[...new Set(points.map(p=>p.y))].sort((a,b)=>a-b),lookup=new Map(points.map(p=>[p.x+':'+p.y,p.efficiency]));return heatLookup(xs,ys,lookup,x,y);}
function heatLookup(xs,ys,lookup,x,y){const exact=lookup.get(coordinateKey(x)+':'+coordinateKey(y));if(exact!==undefined)return exact;const bracket=(a,q)=>{if(q<a[0]||q>a.at(-1))return null;if(a.length===1)return q===a[0]?[a[0],a[0]]:null;const j=Math.max(1,a.findIndex(v=>v>=q));return [a[j-1],a[j]];},xb=bracket(xs,x),yb=bracket(ys,y);if(!xb||!yb)return null;const [a,b]=xb,[c,d]=yb,tx=b===a?0:(x-a)/(b-a),ty=d===c?0:(y-c)/(d-c),corners=[[a,c],[b,c],[a,d],[b,d]],v=corners.map(([xx,yy])=>lookup.get(xx+':'+yy));if(v.every(Number.isFinite))return (1-ty)*((1-tx)*v[0]+tx*v[1])+ty*((1-tx)*v[2]+tx*v[3]);return null;}
export function continuousHeatmap(rows,axis='vin',scale=efficiencyScale(rows)){const points=groupedHeatPoints(rows,axis);if(!points.length)return '<p>No valid efficiency points.</p>';const xs=[...new Set(points.map(p=>p.x))].sort((a,b)=>a-b),ys=[...new Set(points.map(p=>p.y))].sort((a,b)=>a-b);if(xs.length<2||ys.length<2)return '<p class="caption">A continuous surface needs at least two power levels and two voltage levels. Sampled values are shown below.</p>'+efficiencyHeatmap(rows,axis,scale);const lookup=new Map(points.map(p=>[p.x+':'+p.y,p.efficiency])),W=620,H=330,L=65,T=20,PW=525,PH=255,nx=80,ny=48,xmin=xs[0],xmax=xs.at(-1),ymin=ys[0],ymax=ys.at(-1),X=x=>L+(x-xmin)/(xmax-xmin)*PW,Y=y=>T+PH-(y-ymin)/(ymax-ymin)*PH;let html=`<svg class="chart continuous-heat" viewBox="0 0 ${W} ${H}" role="img" aria-label="Interpolated efficiency heatmap"><rect x="${L}" y="${T}" width="${PW}" height="${PH}" fill="#e1e5e9"/>`;for(let j=0;j<ny;j++)for(let i=0;i<nx;i++){const x=xmin+(i+.5)/nx*(xmax-xmin),y=ymin+(j+.5)/ny*(ymax-ymin),eta=heatLookup(xs,ys,lookup,x,y);if(eta!==null)html+=`<rect x="${L+i/nx*PW}" y="${T+PH-(j+1)/ny*PH}" width="${PW/nx+.1}" height="${PH/ny+.1}" fill="${efficiencyColour(eta,scale).background}"><title>Interpolated: Pout=${num(x)} W; ${axis}=${num(y)} V; efficiency=${num(eta)}%</title></rect>`;}for(const p of points)html+=`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="4" fill="${efficiencyColour(p.efficiency,scale).background}" stroke="white" stroke-width="2"><title>Sampled: Pout=${p.x} W; ${axis}=${p.y} V; efficiency=${num(p.efficiency)}%; ${p.count} samples averaged</title></circle>`;for(let j=0;j<5;j++){const x=xmin+j/4*(xmax-xmin),y=ymin+j/4*(ymax-ymin);html+=`<text x="${X(x)}" y="${T+PH+20}" text-anchor="middle">${num(x)}</text><text x="${L-8}" y="${Y(y)+4}" text-anchor="end">${num(y)}</text>`;}html+=`<text x="${L+PW/2}" y="${H-8}" text-anchor="middle">Output power [W]</text><text transform="translate(15 ${T+PH/2}) rotate(-90)" text-anchor="middle">${axis==='vin'?'Vin':'Vout'} [V]</text></svg><div class="heat-legend"><strong>Efficiency [%]: ${num(scale.min)}–${num(scale.max)}</strong><div style="height:13px;background:linear-gradient(to right,${stops.map(v=>'rgb('+v.join(',')+')').join(',')})"></div></div><p class="caption">Continuous view: bilinear interpolation only inside fully sampled neighbouring grid rectangles. White-ring markers are original grouped samples. Grey regions lack sufficient data; no extrapolation or filling of unsupported gaps. Display interpolation does not change calculated losses.</p>`;return html;}
